<section class="analytics-domain-section"><div class="analytics-domain-heading"><div><span>Fuel</span><h2>Recorded fuel performance</h2></div></div><section class="analytics-kpi-strip"><x-analytics.kpi label="Fuel Used" :value="number_format($fuel['totalFuel']??0,1).' L'" small="Recorded fuel volume" icon="fa-gas-pump"/><x-analytics.kpi label="Linked Distance" :value="number_format($fuel['totalDistance']??0,1).' km'" small="Distance attached to fuel records" icon="fa-road" tone="green"/><x-analytics.kpi label="Efficiency" :value="number_format($fuel['fleetAverage']??0,2).' km/L'" small="Weighted fleet efficiency" icon="fa-gauge-high" tone="purple"/><x-analytics.kpi label="Units" :value="collect($fuel['busSummaries']??[])->count()" small="Buses represented" icon="fa-bus" tone="yellow"/></section></section>